<script setup lang="ts">
import {onMounted,ref} from 'vue';import {doctorApi,progressApi,tasksApi,type DoctorReport,type ProgressItem,type Task} from '@/lib/api';import Card from '@/components/ui/Card.vue';import Badge from '@/components/ui/Badge.vue';import PipelineTracker from '@/components/domain/PipelineTracker.vue';import TaskRow from '@/components/domain/TaskRow.vue';import {useToast} from '@/composables/useToast';import {useEvents} from '@/composables/useEvents';const {toast}=useToast();const report=ref<DoctorReport|null>(null);const items=ref<ProgressItem[]>([]);const tasks=ref<Task[]>([]);const error=ref('');async function load(){try{[report.value,items.value,tasks.value]=await Promise.all([doctorApi.diagnose(),progressApi.overview(),tasksApi.list()])}catch(e){error.value=e instanceof Error?e.message:'加载失败'}}onMounted(load);useEvents(event=>{if(event.type==='task_status')void load()})
</script>
<template><div class="space-y-6"><PipelineTracker :active="3"/><div v-if="error" class="text-status-missing">{{error}}</div><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Card v-for="[label,value] in [['媒体',items.length],['缺失集',items.reduce((n,x)=>n+x.missing.length,0)],['运行任务',tasks.filter(x=>x.state==='running').length],['调度器',report?.scheduler?.running?'运行中':'已停止']]" :key="label" class="p-4"><p class="text-sm text-muted">{{label}}</p><p class="mt-2 text-2xl font-semibold">{{value}}</p></Card></section><div class="grid gap-5 xl:grid-cols-2"><Card class="p-5"><div class="mb-4 flex items-center justify-between"><h2 class="font-semibold">追更健康度</h2><Badge :tone="items.reduce((n,x)=>n+x.missing.length,0)?'warn':'good'">{{items.length}} 部媒体</Badge></div><div v-for="m in items.slice(0,5)" :key="m.media_id" class="flex justify-between border-t border-border py-3 text-sm"><span>{{m.title}}</span><span class="text-muted">{{m.missing.length}} 集待补</span></div><RouterLink to="/progress" class="inline-flex min-h-[44px] items-center text-sm text-primary">查看全部进度 →</RouterLink></Card><Card class="p-5"><h2 class="mb-4 font-semibold">系统诊断</h2><pre class="overflow-auto whitespace-pre-wrap text-xs text-muted">{{JSON.stringify(report,null,2)}}</pre></Card></div><section class="space-y-3"><div class="flex items-center justify-between"><h2 class="font-semibold">任务队列</h2><RouterLink to="/tasks" class="min-h-[44px] content-center text-sm text-primary">全部任务 →</RouterLink></div><TaskRow v-for="task in tasks.slice(0,3)" :key="task.id" :task="task" @retry="id=>tasksApi.retry(id).then(()=>toast('任务已重新排队','success'))"/></section></div></template>